code:
p {
  font: italic bold 16px Arial, sans-serif;
}

/* 1 valeur (4 côtés) */
div { padding: 15px; }
/* 2 valeurs [Haut/Bas] [Gauche/Droite] */
div { padding: 10px 20px; }
/* 4 valeurs : Haut Droite Bas Gauche */
div { padding: 10px 15px 20px 5px; }

/* 1 valeur : 4 côtés */
div { margin: 20px; }
/* 2 valeurs : [Haut/Bas] [Gauche/Droite] (centrage automatique) */
div { margin: 0 auto; }
/* 4 valeurs : Haut Droite Bas Gauche */
div { margin: 10px 15px 20px 5px; }

/* 1 valeur : les 4 coins identiques */
button { border-radius: 8px; }
/* 4 valeurs : HG HD BD BG */
button { border-radius: 10px 5px 10px 5px; }
/* Cercle parfait */
img { border-radius: 50%; }

body {
  background: #ffffff url("bg.jpg") no-repeat center / cover;
}

button {
  transition: all 0.3s ease 0.1s;
}
button:hover {
  background-color: blue;
}

div {
  animation: clignoter 2s ease 0s infinite alternate;
}
